Lemma tail_client_outside : forall Σ' (m : mem) l1 l2 live0 frs usp a W,
  ART RT Σ' m -> rt_live RT Σ' = l1 ++ l2 -> ivls_in W l1 -> (forall e, In e live0 -> In e l2) ->
  (forall e, In e frs -> In e (rt_frames RT Σ')) -> rt_sp0 RT Σ' - STACK_WIN <= usp ->
